    "amazon q developer": "Amazon Q Developer",
    "aqua trivy": "Aqua Trivy",
    trivy: "Aqua Trivy",
    "octopus deploy": "Octopus Deploy",
    "launch darkly": "LaunchDarkly",
    launchdarkly: "LaunchDarkly",
    "factory.ai": "Factory.ai",
    "black duck": "Black Duck",
    "apache kafka": "Apache Kafka",
    kafka: "Apache Kafka",
    "litmus chaos": "LitmusChaos",
    litmus: "LitmusChaos",
    "nexus repository": "Nexus Repository",
    "noname": "Noname / Salt",
    "noname / salt": "Noname / Salt",
    datadog: "Datadog",
    spinnaker: "Spinnaker",
    backstage: "Backstage",
    circleci: "CircleCI",
